#!/bin/sh
# build-appimage.sh — build the REAL .AppImage with the PINNED
# appimagetool + pinned type2 runtime (issue #56, card 8.E3, W24-C).
#
# The 8.E3 config-driven AppImage lane (supersedes the wave-22
# scripts/release/make-appimage.sh flow for release purposes):
#   * the desktop entry is generated by gen-desktop-entry.sh — the ONE
#     writer shared with the deb/rpm lanes, so all three ship the same
#     entry (Categories/Terminal from packaging.toml [desktop_entry]);
#   * the AppDir bin dir mirrors PACKAGING_LINUX_BINDIR's tail segment
#     (usr/bin — the AppImage spec's own convention), asserted against
#     the config rather than hard-coded;
#   * the icon prefers the real brand asset (product.toml [brand]
#     icon_png_512) and falls back to the deterministic placeholder.
#
# Tool pinning (the doc 11 §3.7 posture — no floating components):
#   APPIMAGETOOL  path to the pinned appimagetool 1.9.1 AppImage
#   RUNTIME_FILE  path to the pinned AppImage type2 runtime — REQUIRED
#                 and passed via --runtime-file so appimagetool never
#                 fetches the ROLLING `continuous` runtime at build
#                 time.
# Both tools are AppImages/ELFs: APPIMAGE_EXTRACT_AND_RUN=1 runs them
# without FUSE (hosted runners and this sandbox have no usable FUSE).
#
# Usage: build-appimage.sh
# Output: DIST_DIR/<slug>-<version>-<arch>-linux.AppImage
# POSIX sh; `bash -n` clean; EXECUTED for real in the local 8.E3 proof
# (docs/packaging/evidence) and in the release workflow's Linux jobs.
set -eu

: "${PRODUCT_NAME:?build-appimage.sh: PRODUCT_NAME not set (run packaging-env.py first)}"
: "${PRODUCT_LOWER:?build-appimage.sh: PRODUCT_LOWER not set}"
: "${PRODUCT_APPSTREAM_ID:?build-appimage.sh: PRODUCT_APPSTREAM_ID not set}"
: "${PRODUCT_ACCENT_COLOR:?build-appimage.sh: PRODUCT_ACCENT_COLOR not set}"
: "${PRODUCT_ICON_PNG_512:?build-appimage.sh: PRODUCT_ICON_PNG_512 not set}"
: "${BIN_DESKTOP:?build-appimage.sh: BIN_DESKTOP not set}"
: "${OS_ID:?build-appimage.sh: OS_ID not set}"
: "${ARCH_ID:?build-appimage.sh: ARCH_ID not set}"
: "${PACKAGING_LINUX_BINDIR:?build-appimage.sh: PACKAGING_LINUX_BINDIR not set (run packaging-env.py first)}"
: "${APPIMAGETOOL:?build-appimage.sh: APPIMAGETOOL not set (pinned appimagetool download — see docs/packaging/README.md)}"
: "${RUNTIME_FILE:?build-appimage.sh: RUNTIME_FILE not set (pinned AppImage type2 runtime — required so no rolling runtime is fetched)}"
TARGET_DIR=${TARGET_DIR:-target}
DIST_DIR=${DIST_DIR:-dist}

ROOT=$(cd "$(dirname -- "$0")/../.." && pwd)
cd "$ROOT"

die() { echo "build-appimage.sh: error: $*" >&2; exit 1; }

[ "$OS_ID" = "linux" ] || die "build-appimage.sh is the Linux lane (OS_ID=${OS_ID})"
[ -x "$APPIMAGETOOL" ] || die "APPIMAGETOOL is not executable: $APPIMAGETOOL"
[ -f "$RUNTIME_FILE" ] || die "RUNTIME_FILE not found: $RUNTIME_FILE"

# The AppImage spec's AppDir convention is usr/bin — derive it from the
# configured FHS bindir and assert the convention instead of assuming
# it (a future packaging.toml change away from usr/bin is caught here,
# not silently mismatched).
appdir_bin="usr/bin"
case "$PACKAGING_LINUX_BINDIR" in
    "$appdir_bin") ;;
    *) die "packaging.toml linux.install_bindir is '$PACKAGING_LINUX_BINDIR' but the AppImage AppDir convention requires '$appdir_bin' — the deb/rpm and AppImage lanes share this path by spec" ;;
esac

bin="$TARGET_DIR/release/$BIN_DESKTOP"
[ -f "$bin" ] || die "missing desktop binary: $bin (build first: cargo build --release --locked)"

stage=$(mktemp -d)
trap 'rm -rf "$stage"' EXIT INT TERM
appdir="$stage/AppDir"
mkdir -p "$appdir/$appdir_bin"

install -m 0755 "$bin" "$appdir/$appdir_bin/$BIN_DESKTOP"

# Minimal AppRun: exec the bundled binary via the AppDir-relative path.
# $BIN_DESKTOP is substituted at BUILD time (cargo metadata [[bin]]
# name, not a runtime value).
cat >"$appdir/AppRun" <<EOF
#!/bin/sh
# Generated by scripts/packaging/build-appimage.sh — DO NOT HAND-EDIT.
HERE=\$(cd "\$(dirname "\$0")" && pwd)
exec "\$HERE/$appdir_bin/${BIN_DESKTOP}" "\$@"
EOF
chmod 0755 "$appdir/AppRun"

# Desktop entry: the ONE shared writer (same content as deb/rpm).
"$ROOT/scripts/packaging/gen-desktop-entry.sh" "$appdir/${PRODUCT_LOWER}.desktop"

# Icon: real brand asset when it exists, documented placeholder if not;
# .DirIcon must be a file or symlink beside the entry.
icon_src="$PRODUCT_ICON_PNG_512"
if [ ! -f "$icon_src" ]; then
    PY=$(command -v python3 || command -v python) ||
        die "neither python3 nor python found on PATH (icon generation needs the stdlib)"
    icon_src="$stage/$PRODUCT_LOWER.png"
    "$ROOT/scripts/release/gen-icon.py" "$icon_src" "$PRODUCT_ACCENT_COLOR"
fi
install -m 0644 "$icon_src" "$appdir/$PRODUCT_LOWER.png"
ln -s "$PRODUCT_LOWER.png" "$appdir/.DirIcon"

mkdir -p "$DIST_DIR"
dist_abs=$(cd "$DIST_DIR" && pwd)
out="$dist_abs/${PRODUCT_LOWER}-${PRODUCT_VERSION:?}-${ARCH_ID}-${OS_ID}.AppImage"

# APPIMAGE_EXTRACT_AND_RUN=1: no FUSE needed on the build host. ARCH is
# passed explicitly so the runtime architecture never depends on
# guessing from the binary's ELF header.
APPIMAGE_EXTRACT_AND_RUN=1 ARCH="$ARCH_ID" "$APPIMAGETOOL" --runtime-file "$RUNTIME_FILE" \
    "$appdir" "$out"
[ -s "$out" ] || die "AppImage is missing or empty: $out"
echo "build-appimage.sh: wrote $out"
